def _hidden_inputs(html):
    html = re.sub(r'<!--(?:(?!<!--).)*-->', '', html)
    hidden_inputs = {}
    for input_el in re.findall(r'(?i)(<input[^>]+>)', html):
        attrs = extract_attributes(input_el)
        if not input_el:
